/**
 * @file Nickname.js
 * 
 * @description A component for entering a nickname. 
 *              It validates the input to ensure it is not empty and passes 
 *              the nickname to the parent component via the `onSubmit` callback function.
 * 
 * @author Karolína Virágová (xvirag00)
 * 
 * @props {function} onSubmit - A function that is called when the user submits 
 *        a valid nickname. The nickname is passed as an argument to this function.
 */

import React, { useState } from 'react';

const Nickname = ({ onSubmit }) => {

  const [nickname, setNickname] = useState('');

  const handleNicknameChange = (e) => {
    setNickname(e.target.value);
  };

  const handleSubmit = () => {
    if (nickname.trim() !== '') {
      onSubmit(nickname);
    } else {

    }
  };

  return (
    <div className="nickname-container">
      <h2>Enter your nickname: </h2>
      <input 
        type="text" 
        placeholder="Karla" 
        value={nickname} 
        onChange={handleNicknameChange} 
      />
      <button onClick={handleSubmit}>Continue</button>
    </div>
  );
};

export default Nickname;
